<?php require __DIR__.'/_layout_start.php'; ?><div class="toolbar"><div><h1>Campus - Eventi</h1><p class="muted">Eventi pubblici e riservati ai CAT.</p></div><a class="btnlink" href="/admin/campus/events/form">Nuovo evento</a></div><table><thead><tr><th>Evento</th><th>Audience</th><th>Data</th><th>Iscrizioni</th><th>Stato</th><th></th></tr></thead><tbody><?php foreach($events as $e):?><tr><td><strong><?= htmlspecialchars($e['title'],ENT_QUOTES,'UTF-8') ?></strong></td><td><span class="badge"><?= htmlspecialchars(strtoupper($e['audience']),ENT_QUOTES,'UTF-8') ?></span></td><td><?= htmlspecialchars(date('d/m/Y H:i',strtotime((string)$e['starts_at'])),ENT_QUOTES,'UTF-8') ?></td><td><?= (int)$e['registrations'] ?></td><td><?= (int)$e['published']?'Pubblicato':'Bozza' ?><?= (int)$e['cancelled']?' · Annullato':'' ?></td><td><a href="/admin/campus/events/form?id=<?= (int)$e['id'] ?>">Modifica</a></td></tr><?php endforeach;?></tbody></table><?php require __DIR__.'/_layout_end.php'; ?>
